    private boolean isPersonalValid() {
        String string = this.binding.aadharNumberET.getText().toString();
        if (!string.equals("")) {
            this.msg = String.valueOf(Verhoeff.validateVerhoeff(string));
        }
        if (this.binding.AadhaarNumber.isChecked()) {
            if (this.binding.aadharNumberET.getText().toString().isEmpty() || this.binding.aadharNumberET.getText().toString().equals("")) {
                showdialog("Alert", "Please Enter Aadhaar Number");
                return false;
            }
            if (!this.binding.aadharNumberET.getText().toString().isEmpty() && this.msg.equals(BooleanUtils.FALSE)) {
                showdialog("Alert", "Please enter correct Aadhar Number");
                return false;
            }
        }
        if (!this.binding.numberET.getText().toString().matches("[6-9][0-9]{9}") && !this.binding.numberET.getText().toString().isEmpty()) {
            showdialog("Alert", "Please enter correct Mobile Number");
            return false;
        }
        if (this.binding.emailET.getText().toString().matches("[a-zA-Z0-9._-]+@[a-z]+\\.+[a-z]+") || this.binding.emailET.getText().toString().isEmpty()) {
            return true;
        }
        showdialog("Alert", "Please enter correct Email ID");
        return false;
    }

    private void openFragment(Fragment fragment, String selectedFragment) {
        FragmentTransaction fragmentTransactionBeginTransaction = requireActivity().getSupportFragmentManager().beginTransaction();
        fragmentTransactionBeginTransaction.replace(R.id.main, fragment, selectedFragment);
        fragmentTransactionBeginTransaction.addToBackStack(fragment.getClass().getName());
        fragmentTransactionBeginTransaction.setTransition(4099);
        fragmentTransactionBeginTransaction.commit();
    }

